<?php require __DIR__.'/app/bootstrap.php';$id=(int)($_POST['product_id']??$_GET['id']??0);$p=query('SELECT id,name FROM products WHERE id=? AND active=1',[$id])->fetch();if(!$p){http_response_code(404);exit('Product not found.');}$error='';$saved=false;
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{submission_limit('restock');$size=(string)($_POST['size']??'');$email=strtolower(trim((string)($_POST['email']??'')));$variant=query('SELECT stock FROM variants WHERE product_id=? AND size=?',[$id,$size])->fetch();if(!$variant||$variant['stock']===null||(int)$variant['stock']>0)throw new DomainException('This size is already available or is not offered. Check the product page.');if(strlen($email)>190||!filter_var($email,FILTER_VALIDATE_EMAIL)||empty($_POST['consent']))throw new DomainException('Enter a valid email and agree to be contacted about this restock.');query("INSERT INTO restock_requests(product_id,size,email) VALUES(?,?,?) ON DUPLICATE KEY UPDATE status='waiting',created_at=NOW()",[$id,$size,$email]);$saved=true;}catch(DomainException $e){$error=$e->getMessage();}}
$variants=query('SELECT size FROM variants WHERE product_id=? AND stock=0',[$id])->fetchAll();render_header('Restock request'); ?>
<main class="page narrow"><h1>Waiting for your size?</h1><h2><?=h($p['name'])?></h2><?php if($saved):?><p class="notice">Request saved. Our team can contact you when this size returns. A request does not reserve stock.</p><?php else:?><?php if($error):?><p class="notice error" role="alert"><?=h($error)?></p><?php endif ?><?php if($variants):?><form method="post"><?=csrf_input()?><input type="hidden" name="product_id" value="<?=$id?>"><label>Sold-out size<select name="size"><?php foreach($variants as $v):?><option><?=h($v['size'])?></option><?php endforeach ?></select></label><label>Your email<input type="email" name="email" maxlength="190" required autocomplete="email"></label><label class="check-label"><input type="checkbox" name="consent" value="1" required><span>I agree to be contacted about this product's restock. This does not subscribe me to marketing.</span></label><button class="button dark">REQUEST RESTOCK UPDATE</button></form><?php else:?><p>All listed sizes are currently available.</p><?php endif ?><?php endif ?><p>To withdraw your request, email urbanwearflawed@gmail.com.</p><a href="<?=url('index.php#shop')?>">Back to shop</a></main><?php render_footer(); ?>
